static inline int odapp_nmt_start_all(void)         { return odapp_nmt_send(0x00, ODAPP_NMT_CMD_START_NODE); }
static inline int odapp_nmt_stop_all(void)          { return odapp_nmt_send(0x00, ODAPP_NMT_CMD_STOP_NODE); }

