// ===== Regenerative brake resistor (chopper) =====
// Some drives expose a vendor-specific parameter for the DC-bus brake chopper turn-on threshold (mV).
// The uploaded EDS files (ISV2-CAN, Kinco FD) do not specify a standard object for this.
// To enable this API, define the following macros to match your device before including this header:
//   #define ODAPP_IDX_REGEN_THRESHOLD     0xFFFF  // Replace with vendor index (e.g., 0x6412)
//   #define ODAPP_SUB_REGEN_THRESHOLD     0x00    // Replace with vendor subindex
//   // Select write width (one of):
//   // #define ODAPP_REGEN_THRESHOLD_U16
//   // #define ODAPP_REGEN_THRESHOLD_U32
//
// Optionally, if the drive requires an explicit enable switch for the brake chopper:
//   #define ODAPP_IDX_REGEN_ENABLE        0xFFFF
//   #define ODAPP_SUB_REGEN_ENABLE        0x00
//   // Value to enable/disable (device-specific):
//   #define ODAPP_REGEN_ENABLE_ON_VALUE   1
//   #define ODAPP_REGEN_ENABLE_OFF_VALUE  0
//
// API:
int odapp_set_regen_threshold_mv(uint8_t node, uint32_t millivolts);
int odapp_set_regen_enable(uint8_t node, bool enable);

