// ===== Unit helpers =====
// Convert acceleration specified as rpm/s to counts/s^2
static inline uint32_t odapp_accel_counts_per_s2_from_rpmps(uint32_t rpm_per_sec, uint32_t counts_per_rev) {
    // counts/s^2 = (rpm/s) * (counts/rev) / 60
    // beware of overflow; compute in 64-bit and clamp
    uint64_t num = (uint64_t)rpm_per_sec * (uint64_t)counts_per_rev;
    uint64_t v = num / 60u;
    if (v > 0xFFFFFFFFu) v = 0xFFFFFFFFu;
    return (uint32_t)v;
}


// ===== High-level startup sequence (per provided flow) =====
// Steps:
// 1) NMT - Reset Nodes (broadcast)        -> odapp_nmt_reset_node(0)
// 2) NMT - Active Node (Start)            -> odapp_nmt_start(node)
// 3) Max torque set                       -> 0x6072:00 (0.1% units)
// 4) Operation Mode Set (Profile Velocity)-> 0x6060:00 = 3
// 5) Acceleration & Deceleration Set      -> 0x6083 / 0x6084 (and optional 0x6085)
// 6) Control Word Set (Run/QuickStop Off/Circuit PowerON/Start) -> odapp_servo_enable(node)
int odapp_set_max_torque_percent(uint8_t node, uint16_t percent_0_to_100);       // writes 0x6072:00 = percent*10
int odapp_set_mode_profile_velocity(uint8_t node);                                // writes 0x6060:00 = 3
int odapp_run_sequence_profile_velocity(uint8_t node,
                                        uint16_t max_torque_percent,             // 0..100 (%)
                                        uint32_t accel_counts_per_s2,
                                        uint32_t decel_counts_per_s2,
                                        uint32_t qstop_counts_per_s2);           // 0 to skip

