// ===== SDO response parsing (generic) =====
typedef enum {
    ODAPP_SDO_RESP_UNKNOWN = 0,
    ODAPP_SDO_RESP_DL_INIT_ACK,   // 0x60 Download response
    ODAPP_SDO_RESP_UL_INIT_ACK,   // 0x4? Upload initiate response (expedited or size-indicated)
    ODAPP_SDO_RESP_ABORT         // 0x80 Abort transfer
} odapp_sdo_resp_type_t;

typedef struct {
    odapp_sdo_resp_type_t type;
    uint8_t  cs_raw;         // data[0]
    uint16_t index;          // data[1..2], little-endian
    uint8_t  sub;
    // Upload expedited fields
    uint8_t  expedited;      // bit1
    uint8_t  size_indicated; // bit0
    uint8_t  n_unused;       // bits 2..3 (0..3)
    uint8_t  data_len;       // 0..4 (for expedited)
    uint8_t  data[4];
    // Abort
    uint32_t abort_code;     // data[4..7], if type==ABORT
} ODAPP_SDOParsed;

// Parse raw 8-byte SDO response payload into ODAPP_SDOParsed.
// Returns 0 on success; <0 on length/format errors.
int odapp_sdo_parse_response(const uint8_t* data, uint8_t len, ODAPP_SDOParsed* out);

// Convert SDO abort code (0x80 frames data[4..7]) to human-readable text.
const char* odapp_sdo_abort_str(uint32_t code);

// Debug print helper
void odapp_sdo_print_parsed(const ODAPP_SDOParsed* p);

// ===== Generic PDO parsing helpers =====
// Mapping entry helpers (CiA-301): 0xIIII SS LL  -> index I, sub S, length bits L
#ifndef ODAPP_MAP_IDX
#define ODAPP_MAP_IDX(m)   (uint16_t)(((m) >> 16) & 0xFFFFu)
#endif
#ifndef ODAPP_MAP_SUB
#define ODAPP_MAP_SUB(m)   (uint8_t) (((m) >>  8) & 0xFFu)
#endif
#ifndef ODAPP_MAP_BITS
#define ODAPP_MAP_BITS(m)  (uint8_t) ((m)        & 0xFFu)
#endif

