int odapp_pdo_get_u16(const uint8_t* data, uint8_t len,
                      const uint32_t* map, uint8_t map_count,
                      uint16_t index, uint8_t sub, uint16_t* out);

int odapp_pdo_get_u32(const uint8_t* data, uint8_t len,
                      const uint32_t* map, uint8_t map_count,
                      uint16_t index, uint8_t sub, uint32_t* out);

