static inline int32_t odapp_rpm_to_counts_per_s(int32_t rpm, uint32_t counts_per_rev) {
    int64_t tmp = (int64_t)rpm * (int64_t)counts_per_rev;
    tmp /= 60;
    if (tmp > INT32_MAX) tmp = INT32_MAX;
    if (tmp < INT32_MIN) tmp = INT32_MIN;
    return (int32_t)tmp;
}

static inline int32_t odapp_counts_per_s_to_rpm(int32_t cps, uint32_t counts_per_rev) {
    int64_t tmp = (int64_t)cps * 60;
    if (counts_per_rev) tmp /= (int64_t)counts_per_rev;
    if (tmp > INT32_MAX) tmp = INT32_MAX;
    if (tmp < INT32_MIN) tmp = INT32_MIN;
    return (int32_t)tmp;
}

